const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Kalahari Desert region (approximate center and bounds)
  const kalahari = ee.Geometry.Polygon([
    [[20, -20], [26, -20], [26, -28], [20, -28], [20, -20]]
  ]);

  // 2. Function to mask clouds in Landsat
  function maskL457Clouds(image) {
    const qa = image.select('QA_PIXEL');
    const cloudMask = qa.bitwiseAnd(1 << 3).eq(0)  // Cloud
                        .and(qa.bitwiseAnd(1 << 4).eq(0)); // Cloud shadow
    return image.updateMask(cloudMask);
  }

  // 3. Function to calculate NDVI
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // 4. Get Landsat data for August 6, 2008
  let col2008 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(kalahari)
    .filterDate('2008-08-01', '2008-08-15')
    .map(maskL457Clouds)
    .map(addNDVI);

  const size2008 = col2008.size().getInfo();
  console.log(`2008-08 Images found: ${size2008}`);

  if (size2008 === 0) {
    console.log('No data for August 2008');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Get Landsat data for April 19, 2009
  let col2009 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(kalahari)
    .filterDate('2009-04-15', '2009-04-25')
    .map(maskL457Clouds)
    .map(addNDVI);

  const size2009 = col2009.size().getInfo();
  console.log(`2009-04 Images found: ${size2009}`);

  if (size2009 === 0) {
    console.log('No data for April 2009');
    console.log('<answer>C1</answer>');
    return;
  }

  // 6. Create median composites
  const img2008 = col2008.median();
  const img2009 = col2009.median();

  // 7. Calculate statistics for 2008
  const stats2008 = img2008.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: kalahari,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const ndvi2008 = stats2008['NDVI_mean'];
  const count2008 = stats2008['NDVI_count'];

  console.log(`2008-08: NDVI=${ndvi2008 ? ndvi2008.toFixed(3) : 'null'}, Pixels=${count2008 || 0}`);

  if (!count2008 || count2008 === 0) {
    console.log('No valid pixels for 2008');
    console.log('<answer>C2</answer>');
    return;
  }

  // 8. Calculate statistics for 2009
  const stats2009 = img2009.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: kalahari,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const ndvi2009 = stats2009['NDVI_mean'];
  const count2009 = stats2009['NDVI_count'];

  console.log(`2009-04: NDVI=${ndvi2009 ? ndvi2009.toFixed(3) : 'null'}, Pixels=${count2009 || 0}`);

  if (!count2009 || count2009 === 0) {
    console.log('No valid pixels for 2009');
    console.log('<answer>C2</answer>');
    return;
  }

  // 9. Validate NDVI values
  if (ndvi2008 === null || ndvi2009 === null || 
      isNaN(ndvi2008) || isNaN(ndvi2009) ||
      ndvi2008 < -1 || ndvi2008 > 1 || ndvi2009 < -1 || ndvi2009 > 1) {
    console.log('Invalid NDVI values');
    console.log('<answer>C3</answer>');
    return;
  }

  // 10. Compare NDVI values
  const difference = ndvi2009 - ndvi2008;
  console.log(`NDVI Difference (2009 - 2008): ${difference.toFixed(3)}`);

  if (ndvi2009 > ndvi2008) {
    console.log('Kalahari was greener in April 2009');
    console.log('<answer>A</answer>');
  } else {
    console.log('Kalahari was NOT greener in April 2009');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
